// Derived sections, rebuilt fresh on every generation (content rule; FR-04/FR-13):
// - Table of Contents with correct page numbers
// - List of Audit Issues: number, risk letter/colour, hyperlinked title, page; owner/target date left blank in draft
// - Audit Issues Dashboard: business areas pre-filled, counts left blank for the auditor
// area_for_improvement observations are EXCLUDED from both the dashboard counts and the issue list (FR-26).
const obs = $input.all().map(i => i.json);
const listable = obs.filter(o => o.risk_rating !== 'area_for_improvement');
const listOfIssues = listable.map((o, idx) => ({
  no: idx + 1, risk_letter: o.risk_rating, title: o.title, hyperlink_target: o.id, page: null, owner: null, target_date: null
}));
return [{ json: { list_of_audit_issues: listOfIssues, observation_count: obs.length } }];

// GR-02 automated structural validation: diff generated doc against the fixed template
// (section order, table shapes, rating labels/colours) before handing back to the auditor.
return $input.all();
